-- -- tables ------------------------------------------------------
create table if not exists public.contracts (
  id uuid not null,
  contract_number character varying not null,
  party_id uuid not null,
  party_name text,
  type character varying not null,
  title character varying not null,
  total_amount numeric,
  status character varying not null,
  voen text,
  created_at timestamp with time zone not null,
  advance_percentage numeric(5,2),
  payment_stages integer,
  payment_terms_notes text,
  end_date date,
  contract_date date,
  expiry_date date,
  attachment_path text
);


-- -- functions ---------------------------------------------------
set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.validate_contract_legal_party()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.type IN ('sale', 'service') THEN
    IF NOT EXISTS (
      SELECT 1
      FROM customers c
      WHERE c.id = NEW.party_id
        AND c.entity_type = 'legal'
        AND COALESCE(TRIM(c.voen), '') <> ''
    ) THEN
      RAISE EXCEPTION 'contract_requires_legal_customer_with_voen';
    END IF;
  ELSIF NEW.type = 'purchase' THEN
    IF NOT EXISTS (
      SELECT 1
      FROM suppliers s
      WHERE s.id = NEW.party_id
        AND s.entity_type = 'legal'
        AND COALESCE(TRIM(s.voen), '') <> ''
    ) THEN
      RAISE EXCEPTION 'contract_requires_legal_supplier_with_voen';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;


